import{_ as a,o as t,c as n,h as o}from"./chunks/framework.DC5NoOP7.js";const m=JSON.parse('{"title":"A little about me","description":"Keith Williams on a lifetime of building with computers, teaching at NJIT, and helping people find their way with new technology.","frontmatter":{"title":"A little about me","description":"Keith Williams on a lifetime of building with computers, teaching at NJIT, and helping people find their way with new technology."},"headers":[],"relativePath":"about.md","filePath":"about.md"}'),r={name:"about.md"};function i(s,e,h,l,d,p){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="a-little-about-me" tabindex="-1">A little about me <a class="header-anchor" href="#a-little-about-me" aria-label="Permalink to &quot;A little about me&quot;">​</a></h1><p><strong>I&#39;ve been curious about computers for as long as I can remember. Teaching became a way to share that curiosity.</strong></p><p>My father was a mainframe systems lead operator at Alcoa, so computers were part of my world early on. For Christmas in 1983, I received a Tandy TRS-80 Color Computer 2 and started teaching myself to program. There was something wonderful about making a machine do something that had only been an idea a few minutes earlier.</p><p>That feeling has stayed with me through a lot of changes in technology.</p><h2 id="building-things-teaching-people" tabindex="-1">Building things, teaching people <a class="header-anchor" href="#building-things-teaching-people" aria-label="Permalink to &quot;Building things, teaching people&quot;">​</a></h2><p>I began teaching at NJIT as an adjunct in 2002. Over more than two decades, I&#39;ve developed courses and helped shape the Web and Information Systems program. Today I&#39;m a Senior University Lecturer and director of the B.S. in Enterprise AI.</p><p>I enjoy working with students as they become people who can build, explain, question, and improve things. The projects matter, but so does the confidence that comes from figuring something out and making it work.</p><p>I&#39;ve also built software outside the classroom, including Showedme.net, a web application framework and learning management system, and Wrkbench, an iOS collaboration app. I mention them as part of my history, not as products I&#39;m offering here today.</p><h2 id="learning-beyond-my-own-classroom" tabindex="-1">Learning beyond my own classroom <a class="header-anchor" href="#learning-beyond-my-own-classroom" aria-label="Permalink to &quot;Learning beyond my own classroom&quot;">​</a></h2><p>Before and alongside my university work, I taught children about computers through AmeriCorps at an urban after-school youth center in Pittsburgh. I&#39;ve also worked with high schools.</p><p>In Zambia, I taught software engineering and worked with government teams on e-government services and development practices, including user-experience design and prototyping. Those experiences put technology in a wider context: who needs it, what they are trying to accomplish, and what makes it useful in their circumstances.</p><p>NJIT has written about that work in <a href="https://news.njit.edu/inspiring-students-njit-africa" target="_blank" rel="noreferrer">Inspiring Students from NJIT to Africa</a> and <a href="https://news.njit.edu/njit-lecturer-helps-digitize-government-services-zambia" target="_blank" rel="noreferrer">helping digitize government services in Zambia</a>.</p><h2 id="why-ai-has-my-attention" tabindex="-1">Why AI has my attention <a class="header-anchor" href="#why-ai-has-my-attention" aria-label="Permalink to &quot;Why AI has my attention&quot;">​</a></h2><p>I started using ChatGPT shortly after it launched. What interested me was not just that it could produce answers, but that it could change how we learn, design, and build.</p><p>My current interests include AI-assisted software development, tools that connect answers to their sources, and the relationship between knowledge graphs and retrieval. You can explore some of that through the <a href="/knowledge-lab/">Knowledge Lab</a> and my <a href="/#projects">public projects</a>.</p><p>I also use AI to help organize ongoing work. <a href="/life-tracker">Life Tracker</a> explains that approach: keep a clear record, check what actually happened, and make the next step easier. It is a working method, not a promise that an assistant can do everything on its own.</p><h2 id="ideas-i-m-exploring" tabindex="-1">Ideas I&#39;m exploring <a class="header-anchor" href="#ideas-i-m-exploring" aria-label="Permalink to &quot;Ideas I&#39;m exploring&quot;">​</a></h2><p>I&#39;d like practical AI education to reach beyond university classrooms. One idea from my earlier site, <strong>EverydayAI Newark</strong>, imagined paid workshops helping support free community learning and opportunities for students to demonstrate their work.</p><p>That is an idea, not an operating program or a promise of placements, partnerships, or scheduled events. The part I still care about is simple: people should have a useful place to start, and a chance to learn by doing.</p><p>More broadly, I&#39;m asking how education should change when AI can do more of the work. My <a href="/research">research interests</a> are questions I&#39;m exploring, not settled answers.</p><h2 id="let-s-compare-notes" tabindex="-1">Let&#39;s compare notes <a class="header-anchor" href="#let-s-compare-notes" aria-label="Permalink to &quot;Let&#39;s compare notes&quot;">​</a></h2><p>If you&#39;re learning, teaching, or building something interesting, I&#39;d like to hear what you&#39;re finding. See <a href="/teaching">how I teach</a>, connect on <a href="https://www.linkedin.com/in/keithwilliams5/" target="_blank" rel="noreferrer">LinkedIn</a>, visit my <a href="https://people.njit.edu/profile/kwilliam" target="_blank" rel="noreferrer">NJIT faculty profile</a>, or <a href="/#conversation">start a public conversation</a>.</p><p><em>Adapted from my earlier <a href="https://eaikw.com/about/" target="_blank" rel="noreferrer">About page</a>. This is my personal account of my background; views on this site are my own.</em></p>',23)])])}const u=a(r,[["render",i]]);export{m as __pageData,u as default};
